/* =========================================================
   ICASH — Landing Page
========================================================= */
route('landing', function(){
  navbar();
  const hero = el(`
  <div class="hero">
    <div class="wrap hero-grid">
      <div>
        <div class="eyebrow"><span class="dot"></span> FACE AUTHENTICATION ACTIVE</div>
        <h1 class="display">Bank Without<br><span class="grad">Your Card.</span></h1>
        <p class="lede">Authenticate with your face. Access your money securely. Send, withdraw, and manage transactions without carrying a physical card.</p>
        <div class="hero-cta">
          <button class="btn btn-primary" id="heroRegisterBtn" aria-label="Create a new iCash account" onclick="nav('register')">Register</button>
          <button class="btn btn-ghost" id="heroLoginBtn" aria-label="Log in to your iCash account" onclick="nav('login')">Login</button>
        </div>
        <div style="display:flex;gap:10px;flex-wrap:wrap;">
          <span class="pill ok">${iconSvg('check')} Cardless</span>
          <span class="pill ok">${iconSvg('shield')} Secure</span>
          <span class="pill ok">${iconSvg('contact')} Accessible</span>
        </div>
      </div>
      <div class="hero-visual">
        <canvas id="heroCanvas"></canvas>
        <div class="scan-caption">FACE AUTHENTICATION ACTIVE<span class="sub">CARDLESS · SECURE · ACCESSIBLE</span></div>
      </div>
    </div>
  </div>`);
  mount(hero);

  // Wire buttons AFTER mount so they are in the live DOM
  const heroRegisterBtn = document.getElementById('heroRegisterBtn');
  const heroLoginBtn = document.getElementById('heroLoginBtn');
  if (heroRegisterBtn) {
    heroRegisterBtn.addEventListener('click', () => nav('register'));
    heroRegisterBtn.onclick = () => nav('register');
  }
  if (heroLoginBtn) {
    heroLoginBtn.addEventListener('click', () => nav('login'));
    heroLoginBtn.onclick = () => nav('login');
  }

  initHeroScene();

  mount(el(`
  <div class="section" id="how">
    <div class="wrap">
      <div class="section-head"><h2>How iCash works</h2><p>Four steps between you and your money — no plastic required.</p></div>
      <div class="steps4">
        <div class="card step-card"><div class="step-num">01</div><div class="step-icon">${iconSvg('contact')}</div><h3>Register</h3><p>Create your secure iCash identity in minutes.</p></div>
        <div class="card step-card"><div class="step-num">02</div><div class="step-icon">${iconSvg('face')}</div><h3>Verify your face</h3><p>Complete face authentication and liveness verification.</p></div>
        <div class="card step-card"><div class="step-num">03</div><div class="step-icon">${iconSvg('shield')}</div><h3>Access your wallet</h3><p>Use your face instead of a physical card.</p></div>
        <div class="card step-card"><div class="step-num">04</div><div class="step-icon">${iconSvg('send')}</div><h3>Transact</h3><p>Withdraw, send, or receive money securely.</p></div>
      </div>
    </div>
  </div>`));

  mount(el(`
  <div class="section" id="features">
    <div class="wrap">
      <div class="section-head"><h2>Built for every user</h2><p>One interface, tuned to who's using it.</p></div>
      <div class="feat-strip">
        <div class="card feat"><h4>${iconSvg('contact')} Senior Citizen Mode</h4><p>Users aged 60+ automatically get larger text, simplified navigation, and extra transaction confirmations — no separate app.</p></div>
        <div class="card feat"><h4>${iconSvg('alert')} Emergency PIN</h4><p>A dedicated PIN quietly triggers a simulated emergency protocol — notifying your emergency contact and locking transactions.</p></div>
        <div class="card feat"><h4>${iconSvg('shield')} Liveness Verified</h4><p>Single-face detection plus a blink-based liveness check stops screenshots and photos from being used to authenticate.</p></div>
      </div>
    </div>
  </div>`));

  const secSection = el(`
  <div class="section" id="security">
    <div class="wrap">
      <div class="glass" style="padding:34px; display:flex; align-items:center; gap:28px; flex-wrap:wrap;">
        <div style="flex:1; min-width:240px;">
          <div class="eyebrow">SECURITY, BY DESIGN</div>
          <h2 style="font-family:var(--font-d); font-size:24px; margin:10px 0;">One face. One person. Verified live.</h2>
          <p style="color:var(--muted); font-size:14px; line-height:1.6;">If more than one face enters the frame, scanning stops immediately and access is denied until you restart the camera with only yourself visible. All biometric data in this prototype is simulated and never leaves your browser.</p>
        </div>
        <button class="btn btn-primary" id="secRegisterBtn" aria-label="Create a new iCash account" onclick="nav('register')">Create your iCash ID</button>
      </div>
    </div>
  </div>`);
  mount(secSection);

  // Wire security section CTA after mount
  const secRegisterBtn = document.getElementById('secRegisterBtn');
  if (secRegisterBtn) {
    secRegisterBtn.addEventListener('click', () => nav('register'));
    secRegisterBtn.onclick = () => nav('register');
  }

  mount(el(`
  <footer><div class="wrap fr">
    <div>© 2026 iCash — demo prototype. All financial data shown is simulated.</div>
    <div>Built for accessibility · face-first, card-never</div>
  </div></footer>`));
});


/* ---------- HERO 3D WIREFRAME BUST (Lee Perry-Smith Scan) ---------- */
function initHeroScene(){
  const cv = document.getElementById('heroCanvas');
  if(!cv) {return;}
  const ctx = cv.getContext('2d');
  if(!ctx) {return;}

  let W = 0, H = 0;
  function resize(){
    const r = cv.getBoundingClientRect(), d = Math.min(window.devicePixelRatio || 1, 2);
    W = r.width || 500; H = r.height || 420;
    cv.width = W * d; cv.height = H * d;
    ctx.setTransform(d, 0, 0, d, 0, 0);
  }
  resize();
  window.addEventListener('resize', resize);

  /* ---------- parametric bust: head + neck + shoulders ---------- */
  const Y0 = 1.26, Y1 = -2.7, COLS = 80, ROWS = 72, N = (ROWS + 1) * COLS;
  const bx = new Float32Array(N), by = new Float32Array(N), bz = new Float32Array(N);
  (()=>{
    const bin = atob("");
    const u8 = new Uint8Array(bin.length);
    for(let i = 0; i < bin.length; i++) {u8[i] = bin.charCodeAt(i);}
    const q = new Int16Array(u8.buffer);
    for(let i = 0; i < N; i++){
      bx[i] = q[i * 3] / 8000;
      by[i] = q[i * 3 + 1] / 8000;
      bz[i] = q[i * 3 + 2] / 8000;
    }
  })();

  const sx = new Float32Array(N), sy = new Float32Array(N), vx = new Float32Array(N), vy = new Float32Array(N), vz = new Float32Array(N);
  const stars = Array.from({length: 60}, ()=>({ x: Math.random(), y: Math.random(), r: Math.random() * 1.1 + 0.3, p: Math.random() * 6.28 }));

  /* ---------- pointer interaction ---------- */
  let ang = 0.7, drag = false, lx = 0;
  cv.style.cursor = 'grab';
  cv.style.touchAction = 'none';
  cv.addEventListener('pointerdown', e => {
    drag = true; lx = e.clientX;
    cv.style.cursor = 'grabbing';
    cv.setPointerCapture(e.pointerId);
  });
  cv.addEventListener('pointermove', e => {
    if(drag){ ang += (e.clientX - lx) * 0.012; lx = e.clientX; }
  });
  const stopDrag = () => { drag = false; cv.style.cursor = 'grab'; };
  ['pointerup','pointercancel','pointerleave'].forEach(ev => cv.addEventListener(ev, stopDrag));

  /* ---------- render loop ---------- */
  let last = performance.now();
  let _rafId = null;

  function frame(t){
    if(!cv.isConnected){
      window.removeEventListener('resize', resize);
      return;
    }
    const dt = Math.min(0.05, (t - last) / 1000);
    last = t;
    if(!drag) {ang += 0.5 * dt;}

    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = '#070d14';
    ctx.fillRect(0, 0, W, H);

    const cx = W / 2, cy = H * 0.48, R = W * 0.28, u = R * 0.38;

    // Background starfield
    for(const s of stars){
      ctx.globalAlpha = 0.3 + 0.35 * Math.sin(t * 0.001 + s.p);
      ctx.fillStyle = '#3ab4e0';
      ctx.beginPath();
      ctx.arc(s.x * W, s.y * H, s.r, 0, 6.283);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // Outer subtle perspective ring
    ctx.strokeStyle = 'rgba(60, 130, 160, 0.3)';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.ellipse(cx, cy, R * (0.1 + 0.2 * Math.abs(Math.cos(ang * 0.5))), R * 1.18, 0, 0, 6.283);
    ctx.stroke();

    // Orbital ring back half
    const ox = R * 0.89, oy = R * 0.15, oc = cy - R * 0.42, orb = Math.max(1.5, R * 0.014);
    ctx.strokeStyle = '#2a9d8a';
    ctx.lineWidth = orb;
    ctx.beginPath();
    ctx.ellipse(cx, oc, ox, oy, 0, Math.PI, Math.PI * 2);
    ctx.stroke();

    // Transform 3D mesh vertices
    const c = Math.cos(ang), s = Math.sin(ang), F = 6, pc = Math.cos(0.12), ps = Math.sin(0.12);
    for(let i = 0; i < N; i++){
      const xr = bx[i] * c + bz[i] * s, zr = -bx[i] * s + bz[i] * c;
      const y2 = by[i] * pc - zr * ps, z2 = by[i] * ps + zr * pc, k = F / (F - z2);
      vx[i] = xr; vy[i] = y2; vz[i] = z2;
      sx[i] = cx + xr * u * k; sy[i] = cy - (y2 + 0.75) * u * k;
    }

    const scan = Y1 + (Y0 - Y1) * (0.5 + 0.5 * Math.sin(t * 0.0009));
    const lw = Math.max(0.5, W / 800);
    ctx.globalCompositeOperation = 'lighter';
    const back = new Path2D();

    for(let r = 0; r < ROWS; r++){
      const yq = (by[r * COLS] + by[(r + 1) * COLS]) / 2, near = Math.max(0, 1 - Math.abs(yq - scan) / 0.22);
      for(let q = 0; q < COLS; q++){
        const i0 = r * COLS + q, i1 = r * COLS + (q + 1) % COLS, i2 = (r + 1) * COLS + (q + 1) % COLS, i3 = (r + 1) * COLS + q;
        const cr = (sx[i1] - sx[i0]) * (sy[i3] - sy[i0]) - (sy[i1] - sy[i0]) * (sx[i3] - sx[i0]);
        if(cr <= 0){
          back.moveTo(sx[i0], sy[i0]); back.lineTo(sx[i1], sy[i1]); back.lineTo(sx[i2], sy[i2]); back.lineTo(sx[i3], sy[i3]); back.closePath();
          continue;
        }
        const ax = vx[i1] - vx[i0], ay = vy[i1] - vy[i0], az = vz[i1] - vz[i0],
              bx_ = vx[i3] - vx[i0], by_ = vy[i3] - vy[i0], bz_ = vz[i3] - vz[i0];
        const nx = ay * bz_ - az * by_, ny = az * bx_ - ax * bz_, nz = ax * by_ - ay * bx_;
        const rim = 1 - Math.abs(nz) / Math.sqrt(nx * nx + ny * ny + nz * nz + 1e-9);
        const rr = rim * rim, lit = Math.max(0, -(nx * 0.45 + ny * 0.6 + nz * 0.66)) / Math.sqrt(nx * nx + ny * ny + nz * nz + 1e-9);
        ctx.fillStyle = 'rgba(20,80,210,' + (0.04 + 0.28 * rr + 0.22 * lit * lit + near * 0.12).toFixed(3) + ')';
        ctx.strokeStyle = 'rgba(' + Math.round(50 + 140 * rim + near * 60) + ',' + Math.round(140 + 100 * rim + 60 * lit + near * 60) + ',255,' + Math.min(1, 0.28 + 0.6 * rim + 0.3 * lit + near * 0.5).toFixed(2) + ')';
        ctx.lineWidth = lw * (1 + near * 0.8);
        ctx.beginPath(); ctx.moveTo(sx[i0], sy[i0]); ctx.lineTo(sx[i1], sy[i1]); ctx.lineTo(sx[i2], sy[i2]); ctx.lineTo(sx[i3], sy[i3]); ctx.closePath();
        ctx.fill(); ctx.stroke();
      }
    }
    ctx.strokeStyle = 'rgba(40,100,220,0.13)';
    ctx.lineWidth = lw * 0.8;
    ctx.stroke(back);
    ctx.globalCompositeOperation = 'source-over';

    // Holographic laser scan line
    const sY = cy - (scan + 0.75) * u;
    const sg = ctx.createLinearGradient(cx - R * 0.9, 0, cx + R * 0.9, 0);
    sg.addColorStop(0, 'rgba(90,220,255,0)');
    sg.addColorStop(0.5, 'rgba(90,220,255,0.5)');
    sg.addColorStop(1, 'rgba(90,220,255,0)');
    ctx.fillStyle = sg;
    ctx.fillRect(cx - R * 0.9, sY - 0.5, R * 1.8, 1);

    // Orbital ring front half + travelling glowing node
    ctx.strokeStyle = '#2a9d8a';
    ctx.lineWidth = orb;
    ctx.beginPath();
    ctx.ellipse(cx, oc, ox, oy, 0, 0, Math.PI);
    ctx.stroke();

    const oa = t * 0.0013;
    ctx.fillStyle = '#7ff3d6';
    ctx.shadowColor = '#2ad9b0';
    ctx.shadowBlur = 10;
    ctx.beginPath();
    ctx.arc(cx + ox * Math.cos(oa), oc + oy * Math.sin(oa), 3, 0, 6.283);
    ctx.fill();
    ctx.shadowBlur = 0;

    // Glowing cyan boundary ring
    ctx.strokeStyle = '#3ab4e0';
    ctx.lineWidth = Math.max(2, R * 0.025);
    ctx.shadowColor = '#3ab4e0';
    ctx.shadowBlur = 12;
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, 6.283);
    ctx.stroke();
    ctx.shadowBlur = 0;

    _rafId = requestAnimationFrame(frame);
  }
  _rafId = requestAnimationFrame(frame);
}
